function decodeBase64(base64) {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

function serveInlineAsset(request) {
  if (request.method !== "GET" && request.method !== "HEAD") {
    return new Response("Method not allowed", {
      status: 405,
      headers: { allow: "GET, HEAD" },
    });
  }

  const url = new URL(request.url);
  let pathname;

  try {
    pathname = decodeURIComponent(url.pathname);
  } catch {
    return new Response("Bad request", { status: 400 });
  }

  if (pathname === "/") pathname = "/index.html";

  const asset = INLINE_ASSETS.get(pathname);
  if (!asset) return new Response("Not found", { status: 404 });

  const headers = {
    "content-type": asset.contentType,
    "cache-control": pathname === "/index.html" ? "no-store" : "public, max-age=3600",
  };

  if (request.method === "HEAD") return new Response(null, { headers });

  const body = asset.encoding === "base64" ? decodeBase64(asset.body) : asset.body;
  return new Response(body, { headers });
}
